#include "mask-core.hpp"
int main(int argc,char**argv){ifstream f(argv[1]);f>>ct;assert(ct.size()==385);width=stoi(argv[2]);ifstream coordinates(argv[3]);for(int&v:coord)coordinates>>v;for(int n=2;n<=5;n++){int size=1;for(int j=0;j<n;j++)size*=26;grams[n].assign(size,-n);ifstream model(n<4?string(argv[4])+"/model"+to_string(n)+".tsv":string(argv[5])+"/ring-"+to_string(n)+"grams.tsv");assert(model);string s;float val;while(model>>s>>val){int ix=0;for(char c:s)ix=ix*26+c-'a';grams[n][ix]=val;}}for(int i=0;i<26;i++)P[i]=i;for(m=20;m<=30;m++)for(int offset=0;offset<26;offset++){for(int i=0;i<26;i++)O[i]=(i+offset)%26;vector<pair<float,pair<int,Node>>>pool;for(anchor=0;anchor<52;anchor++){precompute();Node first{};first.h[0]=0;vector<Node>beam{first};for(int r=1;r<m;r++){vector<Node>next;for(auto&x:beam)for(int h=x.h[r-1]+1;h<=52-(m-r);h++){Node y=x;y.h[r]=h;y.score=x.score+inside(r,y);if(r==m-1)y.score+=wrap(y);next.push_back(y);}int keep=min(width,int(next.size()));if(keep<next.size())nth_element(next.begin(),next.begin()+keep,next.end(),[](auto&a,auto&b){return a.score>b.score;});next.resize(keep);beam=std::move(next);}sort(beam.begin(),beam.end(),[](auto&a,auto&b){return a.score>b.score;});for(int rank=0;rank<min(4,int(beam.size()));rank++)pool.push_back({beam[rank].score,{anchor,beam[rank]}});sort(pool.begin(),pool.end(),[](auto&a,auto&b){return a.first>b.first;});if(pool.size()>4)pool.resize(4);}for(int rank=0;rank<pool.size();rank++){anchor=pool[rank].second.first;precompute();auto x=pool[rank].second.second;cout<<m<<'\t'<<offset<<'\t'<<anchor<<'\t'<<rank<<'\t'<<x.score<<'\t';for(int j=0;j<m;j++)cout<<(j?",":"")<<(anchor+x.h[j])%52;cout<<'\t'<<plaintext(x)<<'\n'<<flush;}cerr<<m<<' '<<offset<<" done\n"<<flush;}}
